from decimal import Decimal, ROUND_HALF_UP

CENTS = Decimal('0.01')


def _to_decimal(value):
    return Decimal(str(value))


def _round_cents(value):
    return value.quantize(CENTS, rounding=ROUND_HALF_UP)


def _format_cents(value):
    cents = _round_cents(value)
    if cents == 0:
        cents = Decimal('0.00')
    return str(cents)


def invoice(lines, tax_rate):
    rate = _to_decimal(tax_rate)
    subtotal = Decimal('0')
    tax = Decimal('0')
    for row in lines:
        line_amount = _round_cents(_to_decimal(row['unit_price']) * _to_decimal(row['qty']))
        subtotal += line_amount
        if row.get('taxable', True):
            tax += _round_cents(line_amount * rate)
    total = subtotal + tax
    return {
        'subtotal': _format_cents(subtotal),
        'tax': _format_cents(tax),
        'total': _format_cents(total),
    }
